package jump

// The stages' maps, one string per row of tiles: '#' ground, '=' a solid
// block, 'd' dirt the dash breaks, '-' a cloud to stand on from above,
// '^' spikes, 'o' a gem, 'C' a checkpoint, 'G' the goal flag, 'P' the
// start, and 'b', 'm', 's' a bug, a moth and a spiky bug.
type stage struct {
	name string
	rows [rows]string
}

